'use strict';(()=>{const clean=()=>{const h=location.hash||'';if(h==='#/'||h==='#')history.replaceState(history.state,'','/');else if(h.startsWith('#/'))history.replaceState(history.state,'',h.slice(1))};addEventListener('hashchange',()=>queueMicrotask(clean));addEventListener('novelnest:route-rendered',clean);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',clean,{once:true});else clean()})();
